import { test, expect } from '@playwright/test';

test.describe('Checkbox Toggle Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
  });

  test('should have two checkboxes with correct initial states', async ({ page }) => {
    const checkboxes = page.locator('input[type="checkbox"]');

    await expect(checkboxes).toHaveCount(2);

    const firstCheckbox = checkboxes.nth(0);
    const secondCheckbox = checkboxes.nth(1);

    await expect(firstCheckbox).not.toBeChecked();
    await expect(secondCheckbox).toBeChecked();
  });

  test('should check first checkbox and make both checked', async ({ page }) => {
    const checkboxes = page.locator('input[type="checkbox"]');
    const firstCheckbox = checkboxes.nth(0);
    const secondCheckbox = checkboxes.nth(1);

    await firstCheckbox.check();

    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).toBeChecked();
  });

  test('should uncheck second checkbox leaving only first checked', async ({ page }) => {
    const checkboxes = page.locator('input[type="checkbox"]');
    const firstCheckbox = checkboxes.nth(0);
    const secondCheckbox = checkboxes.nth(1);

    await firstCheckbox.check();
    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).toBeChecked();

    await secondCheckbox.uncheck();

    await expect(firstCheckbox).toBeChecked();
    await expect(secondCheckbox).not.toBeChecked();
  });

  test('should toggle checkbox states independently', async ({ page }) => {
    const checkboxes = page.locator('input[type="checkbox"]');
    const firstCheckbox = checkboxes.nth(0);
    const secondCheckbox = checkboxes.nth(1);

    await expect(firstCheckbox).not.toBeChecked();
    await expect(secondCheckbox).toBeChecked();

    await firstCheckbox.click();
    await expect(firstCheckbox).toBeChecked();

    await secondCheckbox.click();
    await expect(secondCheckbox).not.toBeChecked();

    await firstCheckbox.click();
    await expect(firstCheckbox).not.toBeChecked();

    await secondCheckbox.click();
    await expect(secondCheckbox).toBeChecked();
  });
});
